import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const GITHUB_BASE = 'https://github.com/anishishotasff/CodeWhisper/releases/latest/download';

const links = ['Features', 'Demo', 'How it works', 'Pricing', 'Download'];

const downloadOptions = [
  {
    icon: '🖥',
    label: 'Windows',
    sub: 'Windows 10 / 11 · 64-bit',
    href: `${GITHUB_BASE}/CodeWhisper-Setup-1.0.0.exe`,
    color: '#0078d4',
  },
  {
    icon: '🍎',
    label: 'macOS',
    sub: 'Intel & Apple Silicon',
    href: `${GITHUB_BASE}/CodeWhisper-1.0.0.dmg`,
    color: '#a855f7',
  },
];

export default function Navbar() {
  const [scrolled, setScrolled]     = useState(false);
  const [dropOpen, setDropOpen]     = useState(false);
  const dropRef                     = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Close dropdown on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (dropRef.current && !dropRef.current.contains(e.target as Node)) {
        setDropOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <motion.nav
      initial={{ y: -80, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.6, ease: 'easeOut' }}
      style={{
        position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
        padding: '0 24px',
        background: scrolled ? 'rgba(10,10,15,0.88)' : 'transparent',
        backdropFilter: scrolled ? 'blur(20px)' : 'none',
        borderBottom: scrolled ? '1px solid rgba(255,255,255,0.06)' : 'none',
        transition: 'all 0.3s ease',
      }}
    >
      <div className="container" style={{ display: 'flex', alignItems: 'center', height: 64, gap: 4 }}>

        {/* Logo */}
        <motion.a
          href="#"
          style={{ display: 'flex', alignItems: 'center', gap: 10, textDecoration: 'none', marginRight: 16 }}
          whileHover={{ scale: 1.03 }}
        >
          <span style={{ fontSize: 22 }}>🪄</span>
          <span style={{ fontSize: 17, fontWeight: 800, color: '#f1f5f9', letterSpacing: '-0.5px' }}>
            Code<span className="gradient-text">Whisper</span>
          </span>
        </motion.a>

        {/* Nav links */}
        {links.map(link => (
          <motion.a
            key={link}
            href={`#${link.toLowerCase().replace(/\s+/g, '-')}`}
            style={{
              color: 'rgba(241,245,249,0.6)',
              textDecoration: 'none',
              fontSize: 14, fontWeight: 500,
              padding: '6px 12px', borderRadius: 8,
            }}
            whileHover={{ color: '#f1f5f9', backgroundColor: 'rgba(255,255,255,0.06)' }}
          >
            {link}
          </motion.a>
        ))}

        {/* Spacer */}
        <div style={{ flex: 1 }} />

        {/* Download dropdown */}
        <div ref={dropRef} style={{ position: 'relative' }}>
          <motion.button
            onClick={() => setDropOpen(v => !v)}
            style={{
              display: 'flex', alignItems: 'center', gap: 8,
              background: 'linear-gradient(135deg, #7c3aed, #06b6d4)',
              color: '#fff', border: 'none', cursor: 'pointer',
              fontSize: 14, fontWeight: 700,
              padding: '9px 18px', borderRadius: 10,
              boxShadow: '0 0 20px rgba(124,58,237,0.4)',
              fontFamily: 'inherit',
            }}
            whileHover={{ scale: 1.04, boxShadow: '0 0 32px rgba(124,58,237,0.6)' }}
            whileTap={{ scale: 0.96 }}
          >
            ⬇ Download
            <motion.span
              animate={{ rotate: dropOpen ? 180 : 0 }}
              transition={{ duration: 0.2 }}
              style={{ fontSize: 10, display: 'inline-block' }}
            >
              ▼
            </motion.span>
          </motion.button>

          {/* Dropdown menu */}
          <AnimatePresence>
            {dropOpen && (
              <motion.div
                initial={{ opacity: 0, y: -8, scale: 0.96 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -8, scale: 0.96 }}
                transition={{ duration: 0.15, ease: 'easeOut' }}
                style={{
                  position: 'absolute', top: 'calc(100% + 10px)', right: 0,
                  background: 'rgba(15,15,26,0.97)',
                  border: '1px solid rgba(255,255,255,0.1)',
                  borderRadius: 14,
                  overflow: 'hidden',
                  minWidth: 240,
                  boxShadow: '0 20px 60px rgba(0,0,0,0.5), 0 0 0 1px rgba(124,58,237,0.2)',
                  backdropFilter: 'blur(20px)',
                  zIndex: 200,
                }}
              >
                {/* Header */}
                <div style={{
                  padding: '10px 16px 8px',
                  fontSize: 11, fontWeight: 700, letterSpacing: 1,
                  color: 'rgba(241,245,249,0.3)',
                  textTransform: 'uppercase',
                  borderBottom: '1px solid rgba(255,255,255,0.06)',
                }}>
                  Choose your platform
                </div>

                {/* Options */}
                {downloadOptions.map((opt, i) => (
                  <motion.a
                    key={opt.label}
                    href={opt.href}
                    target="_blank"
                    rel="noreferrer"
                    onClick={() => setDropOpen(false)}
                    style={{
                      display: 'flex', alignItems: 'center', gap: 14,
                      padding: '14px 16px',
                      textDecoration: 'none',
                      borderBottom: i < downloadOptions.length - 1 ? '1px solid rgba(255,255,255,0.05)' : 'none',
                    }}
                    whileHover={{ background: 'rgba(255,255,255,0.05)' }}
                  >
                    {/* Platform icon */}
                    <div style={{
                      width: 40, height: 40, borderRadius: 10, flexShrink: 0,
                      background: `${opt.color}18`,
                      border: `1px solid ${opt.color}35`,
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      fontSize: 20,
                    }}>
                      {opt.icon}
                    </div>

                    {/* Text */}
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: 14, fontWeight: 700, color: '#f1f5f9' }}>
                        {opt.label}
                      </div>
                      <div style={{ fontSize: 11, color: 'rgba(241,245,249,0.4)', marginTop: 1 }}>
                        {opt.sub}
                      </div>
                    </div>

                    {/* Arrow */}
                    <span style={{ fontSize: 14, color: opt.color }}>↓</span>
                  </motion.a>
                ))}

                {/* Footer */}
                <div style={{
                  padding: '8px 16px 10px',
                  borderTop: '1px solid rgba(255,255,255,0.06)',
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                }}>
                  <span style={{ fontSize: 11, color: 'rgba(241,245,249,0.3)' }}>
                    🐧 Linux also available
                  </span>
                  <motion.a
                    href="https://github.com/anishishotasff/CodeWhisper/releases"
                    target="_blank"
                    rel="noreferrer"
                    style={{
                      fontSize: 11, color: '#a855f7',
                      textDecoration: 'none', fontWeight: 600,
                    }}
                    whileHover={{ color: '#c084fc' }}
                  >
                    All releases ↗
                  </motion.a>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </motion.nav>
  );
}
